    /**
     * Decodes a variable length integer from a byte array and reports the number of consumed bytes.
     *
     * <p>Overlong encodings are accepted; only frame types have to use the shortest encoding. Use
     * {@link #isMinimalEncoding(byte[], int, int)} to check the latter.</p>
     *
     * @param bytes holding the encoded integer
     * @param offset of the first byte of the encoding
     * @param maxLength number of bytes that may be read
     * @param consumed receives the number of bytes used by the encoding
     * @return the decoded value
     */
    public static long decodeVariableLengthInteger(
            byte[] bytes, int offset, int maxLength, int[] consumed) {
        if (offset >= maxLength) {
            throw new IllegalArgumentException("Truncated variable length integer");
        }
        int first = bytes[offset] & 0xFF;
        int length = 1 << (first >>> 6);
        if (offset + length > maxLength) {
            throw new IllegalArgumentException("Truncated variable length integer");
        }
        long value = first & 0x3F;
        for (int i = 1; i < length; i++) {
            value = (value << 8) | (bytes[offset + i] & 0xFF);
        }
        if (consumed != null) {
            consumed[0] = length;
        }
        return value;
    }

    /**
     * Checks whether the encoding of a value uses the shortest possible width.
     *
     * @param bytes holding the encoding
     * @param offset of the first byte of the encoding
     * @param length number of bytes used by the encoding
     * @return true if the encoding is minimal
     */
    public static boolean isMinimalEncoding(byte[] bytes, int offset, int length) {
        int[] consumed = new int[1];
        long value = decodeVariableLengthInteger(bytes, offset, offset + length, consumed);
        return consumed[0] == length && getEncodedLength(value) == length;
    }

